/ {
	dac_emul_0: dac-emul-0 {
		compatible = "zephyr,dac-emul";
		channel-configs = <&dac_emul_0_cfg_0>;
		#io-channel-cells = <1>;
	};

	dac_emul_0_cfg_0: dac-emul-0-cfg-0 {
		resolution = <12>;
	};

	dac_emul_1: dac-emul-1 {
		compatible = "zephyr,dac-emul";
		channel-configs = <&dac_emul_1_cfg_0>;
		#io-channel-cells = <1>;
	};

	dac_emul_1_cfg_0: dac-emul-1-cfg-0 {
		resolution = <8>;
	};

	dac_emul_1bit: dac-emul-1bit {
		compatible = "zephyr,dac-emul";
		channel-configs = <&dac_emul_1bit_cfg_0>;
		#io-channel-cells = <1>;
	};

	dac_emul_1bit_cfg_0: dac-emul-1bit-cfg-0 {
		resolution = <1>;
	};
};
